// === Tab: mySketch ===
let amplitude = 20;     // Height of vibration
let frequency = 0.1;    // Frequency of wave
let speed = 0.1;        // Speed of vibration
let segments = 40;      // Number of segments in the line
let particles = [];     // Array to store particles
let lines = [];         // Array to store lines
let palette;          // Color palette

function preload() {
  let file = 'city_night_colors.txt';
  // Load each line of the file into an array
  lines = loadStrings(file, (result) => {
    console.log("File loaded successfully:", result);
  }, (err) => {
    console.error("Error loading file:", err);
  });
}

function setup() {
    let canvas = createCanvas(800, 800);
    background("#F6EEE3"); // Light beige background
    frameRate(30);         // Set frame rate
    palette = takeColor(lines);
}

function draw() {
    background("#F6EEE3");

    stroke(0);
    noFill();

    let position = height / 4;

    // Draw the vibrating lines and emit particles with specific directions
    drawWave(position, 1.5, amplitude, 'down');    // First wave emits downward
    drawWave(2 * position, 1, amplitude * 1.5, 'both'); // Second wave emits in both directions
    drawWave(3 * position, 1.5, amplitude, 'up');  // Third wave emits upward

    // Update and display particles
    for (let i = particles.length - 1; i >= 0; i--) {
        particles[i].update();
        particles[i].display();

        // Remove particles that are off-screen
        if (particles[i].isOffScreen()) {
            particles.splice(i, 1);
        }
    }
}

function takeColor(content) {
    let colors = [];
    for (let i = 0; i < content.length; i++) {
      let line = content[i].replace(/\(/g, '').replace(/\)/g, '');
      let [r, g, b] = line.split(",").map(Number);
      let col = color(r, g, b);
      colors.push(col);
    }
    return colors;
  }

function drawWave(position, speedMultiplier, amp, direction = 'up') {
    beginShape();
    let frameOffset = frameCount * speed * speedMultiplier; // Precompute frame offset
    for (let i = 0; i <= segments; i++) {
        let x = map(i, 0, segments, 100, width - 100);
        let y = position + sin(i * frequency + frameOffset) * amp;
        vertex(x, y);

        // Emit a particle at the vertex
        if (frameCount % 5 === 0) { // Emit particles every 5 frames
            particles.push(new Particle(x, y, direction));
        }
    }
    endShape();
}

// Particle class
class Particle {
    constructor(x, y, direction) {
        this.x = x;
        this.y = y;
        this.vy = this.getVelocity(direction); // Vertical speed based on direction
        this.alpha = 255;                      // Transparency
        this.color = random(palette)
    }

    getVelocity(direction) {
        if (direction === 'down') {
            return random(2, 5); // Move downward
        } else if (direction === 'both') {
            return random(-5, 5); // Move in both directions
        } else {
            return random(-2, -5); // Default: Move upward
        }
    }

    update() {
        this.y += this.vy;       // Move vertically
        this.alpha -= 10;        // Fade out faster
    }

    display() {
        noStroke();
        let particleColor = color(red(this.color), green(this.color), blue(this.color), this.alpha); // Set alpha explicitly
        fill(particleColor);
        ellipse(this.x, this.y, 5, 5); // Draw particle as a small circle
    }

    isOffScreen() {
        return this.alpha <= 0;  // Check if the particle is invisible
    }
}

